CREATE TABLE public.staff_crm_view_observations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, staff_admin_id uuid NOT NULL, tab text NOT NULL, filters jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_crm_view_observations TO authenticated; GRANT ALL ON public.staff_crm_view_observations TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.staff_crm_view_observations_id_seq TO service_role;
ALTER TABLE public.staff_crm_view_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY departure_observations_admin_read ON public.staff_crm_view_observations FOR SELECT TO authenticated USING(public.is_active_admin_or_super(auth.uid()));
CREATE INDEX staff_crm_observation_latest ON public.staff_crm_view_observations(staff_admin_id,id DESC);
CREATE TABLE public.staff_crm_departures (archive_id uuid PRIMARY KEY REFERENCES public.staff_leaver_archives(id), captured_at timestamptz NOT NULL DEFAULT now(), view_observed_at timestamptz, tab text, filters jsonb NOT NULL DEFAULT '{}'::jsonb, permissions jsonb NOT NULL DEFAULT '{}'::jsonb, counts jsonb NOT NULL DEFAULT '{}'::jsonb, scope_note text NOT NULL DEFAULT 'Assigned leads and own accessible customers; not a screenshot or a complete management-wide CRM view.');
GRANT SELECT ON public.staff_crm_departures TO authenticated; GRANT ALL ON public.staff_crm_departures TO service_role;
ALTER TABLE public.staff_crm_departures ENABLE ROW LEVEL SECURITY;
CREATE POLICY departure_admin_read ON public.staff_crm_departures FOR SELECT TO authenticated USING(public.is_active_admin_or_super(auth.uid()));
CREATE TABLE public.staff_crm_departure_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, archive_id uuid NOT NULL REFERENCES public.staff_crm_departures(archive_id), kind text NOT NULL, source_id text NOT NULL, record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(archive_id,kind,source_id));
GRANT SELECT ON public.staff_crm_departure_items TO authenticated; GRANT ALL ON public.staff_crm_departure_items TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.staff_crm_departure_items_id_seq TO service_role;
ALTER TABLE public.staff_crm_departure_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY departure_items_admin_read ON public.staff_crm_departure_items FOR SELECT TO authenticated USING(public.is_active_admin_or_super(auth.uid()));
CREATE INDEX departure_item_page ON public.staff_crm_departure_items(archive_id,kind,id);
CREATE INDEX IF NOT EXISTS departure_customer_owner ON public.customers(assigned_to);
CREATE INDEX IF NOT EXISTS departure_customer_credit ON public.customers(sale_credit_admin_user_id);
CREATE OR REPLACE FUNCTION public.staff_crm_locked() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Departure evidence is immutable'; END $$;
REVOKE ALL ON FUNCTION public.staff_crm_locked() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER departure_lock BEFORE UPDATE OR DELETE ON public.staff_crm_departures FOR EACH ROW EXECUTE FUNCTION public.staff_crm_locked();
CREATE TRIGGER departure_item_lock BEFORE UPDATE OR DELETE ON public.staff_crm_departure_items FOR EACH ROW EXECUTE FUNCTION public.staff_crm_locked();
CREATE TRIGGER departure_observation_lock BEFORE UPDATE OR DELETE ON public.staff_crm_view_observations FOR EACH ROW EXECUTE FUNCTION public.staff_crm_locked();
CREATE OR REPLACE FUNCTION public.staff_crm_safe_filters(_filters jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(CASE WHEN jsonb_typeof(_filters)='object' THEN _filters ELSE '{}'::jsonb END) WHERE key IN ('view','status','period','from','to','assignment','sort','source','age','plan','payment','search_omitted') AND jsonb_typeof(value) IN ('string','boolean') AND (value::text ~ '^"[a-zA-Z0-9_.: -]{0,60}"$' OR value::text IN ('true','false')); $$;
REVOKE ALL ON FUNCTION public.staff_crm_safe_filters(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_crm_safe_filters(jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.record_staff_crm_view(_tab text,_filters jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid; BEGIN SELECT id INTO me FROM public.admin_users WHERE user_id=auth.uid() AND is_active AND archived_at IS NULL; IF me IS NULL THEN RAISE EXCEPTION 'Active staff required'; END IF; IF _tab IS NULL OR _tab !~ '^[a-z0-9-]{1,60}$' THEN RAISE EXCEPTION 'Invalid page'; END IF; INSERT INTO public.staff_crm_view_observations(staff_admin_id,tab,filters) VALUES(me,_tab,public.staff_crm_safe_filters(_filters)); END $$;
REVOKE ALL ON FUNCTION public.record_staff_crm_view(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_staff_crm_view(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_crm_pick(_record jsonb,_keys text[]) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(_record) WHERE key=ANY(_keys); $$;
REVOKE ALL ON FUNCTION public.staff_crm_pick(jsonb,text[]) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.staff_crm_capture(_archive uuid,_staff public.admin_users) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET statement_timeout='15s' AS $$
DECLARE observed record; now_at timestamptz:=now(); amount integer; source text; actor text; keys text[]; BEGIN
IF EXISTS(SELECT 1 FROM public.staff_crm_departures WHERE archive_id=_archive) THEN RETURN; END IF;
SELECT * INTO observed FROM public.staff_crm_view_observations WHERE staff_admin_id=_staff.id ORDER BY id DESC LIMIT 1;
INSERT INTO public.staff_crm_departures(archive_id,view_observed_at,tab,filters,permissions) VALUES(_archive,observed.created_at,observed.tab,coalesce(observed.filters,'{}'),jsonb_build_object('role',_staff.role,'permissions',_staff.permissions,'column_masking',_staff.column_masking,'is_active',_staff.is_active,'access_expires_at',_staff.access_expires_at,'export_grants',(SELECT public.staff_crm_pick(to_jsonb(g),ARRAY['can_export_new_leads','can_export_customers','can_see_lead_source']) FROM public.staff_export_grants g WHERE g.admin_user_id=_staff.id),'roles',(SELECT jsonb_agg(r.role) FROM public.user_roles r WHERE r.user_id=_staff.user_id)));
INSERT INTO public.staff_crm_departure_items(archive_id,kind,source_id,record) SELECT _archive,'leads',l.id::text,public.staff_crm_pick(to_jsonb(l),ARRAY['id','first_name','last_name','vehicle_reg','vehicle_make','vehicle_model','status','created_at','assigned_to','assigned_at','call_count','next_action_date','last_contacted_at','quote_amount']) FROM public.sales_leads l WHERE l.assigned_to=_staff.id AND (_staff.role::text NOT IN ('sales','sales_lead') OR NOT coalesce(l.management_hold,false));
INSERT INTO public.staff_crm_departure_items(archive_id,kind,source_id,record) SELECT _archive,'customers',c.id::text,public.staff_crm_pick(to_jsonb(c),ARRAY['id','name','registration_plate','vehicle_make','vehicle_model','signup_date','status','plan_type','assigned_to','sale_credit_admin_user_id']) FROM public.customers c WHERE ((c.assigned_to=_staff.id OR c.sale_credit_admin_user_id=_staff.id) AND NOT coalesce(c.is_deleted,false) AND (_staff.role::text NOT IN ('sales','sales_lead') OR coalesce(c.signup_date,now_at)>=now_at-interval '2 months')) OR (_staff.role::text IN ('sales','sales_lead') AND NOT coalesce(c.is_deleted,false) AND EXISTS(SELECT 1 FROM public.customer_history_access_requests r WHERE r.customer_id=c.id AND r.requester_admin_user_id=_staff.id AND r.status='approved' AND r.expires_at>now_at));
FOR source,actor,keys IN SELECT * FROM (VALUES
('crm_attendance_sessions','admin_user_id',ARRAY['id','started_at','last_seen_at','first_activity_at','last_activity_at','ended_at','end_reason','current_tab']),
('lead_access_events','actor_id',ARRAY['id','lead_id','action','source','occurred_at']),
('staff_work_locations','admin_user_id',ARRAY['id','ip_address','city','country','country_code','isp','is_vpn','device_type','first_seen_at','last_seen_at']),
('admin_user_access_periods','admin_user_id',ARRAY['id','start_date','end_date','reason','started_by','ended_by'])
) AS sources(s,a,k) LOOP
EXECUTE format('INSERT INTO public.staff_crm_departure_items(archive_id,kind,source_id,record) SELECT $1,%L,t.id::text,public.staff_crm_pick(to_jsonb(t),$3) FROM public.%I t WHERE t.%I=$2',source,source,actor) USING _archive,_staff.id,keys;
END LOOP;
SELECT count(*) INTO amount FROM public.staff_crm_departure_items WHERE archive_id=_archive; IF amount>100000 THEN RAISE EXCEPTION 'Departure snapshot exceeds safe size; administrator review required before removal'; END IF;
-- Metadata is finalised inside the creating transaction only; immutable after insert.
END $$;
REVOKE ALL ON FUNCTION public.staff_crm_capture(uuid,public.admin_users) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.staff_archive_open(_admin public.admin_users,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN
INSERT INTO public.staff_leaver_archives(admin_user_id,auth_user_id,staff_name,staff_email,staff_role,trigger_reason,profile_snapshot,created_by) VALUES(_admin.id,_admin.user_id,trim(coalesce(_admin.first_name,'')||' '||coalesce(_admin.last_name,'')),_admin.email,_admin.role::text,_reason,public.staff_crm_pick(to_jsonb(_admin),ARRAY['id','user_id','first_name','last_name','email','role','permissions','is_active','archived_at','last_login','created_at']),auth.uid()) RETURNING id INTO v_id;
PERFORM public.staff_crm_capture(v_id,_admin); RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.staff_leaver_archive_on_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF TG_OP='DELETE' THEN v_id:=public.staff_archive_open(OLD,'removed'); PERFORM public.staff_archive_build_all(v_id); RETURN OLD; END IF; IF (coalesce(OLD.is_active,true) AND NOT coalesce(NEW.is_active,true)) OR (OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL) THEN PERFORM public.staff_archive_open(OLD,CASE WHEN NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN 'archived' ELSE 'deactivated' END); END IF; RETURN NEW; END $$;
DROP TRIGGER admin_users_leaver_archive_update ON public.admin_users;
CREATE TRIGGER a00_staff_departure_capture BEFORE UPDATE OF is_active,archived_at ON public.admin_users FOR EACH ROW EXECUTE FUNCTION public.staff_leaver_archive_on_change();
-- Archive RPC must change staff status first, before clearing membership or queues.
CREATE OR REPLACE FUNCTION public.archive_admin_user_preserve_sales(p_admin_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_caller_role text; BEGIN SELECT role::text INTO v_caller_role FROM public.admin_users WHERE user_id=auth.uid() AND is_active LIMIT 1; IF v_caller_role IS NULL OR v_caller_role NOT IN ('super_admin','admin','sales_manager') THEN RAISE EXCEPTION 'Only management can archive staff users'; END IF; IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE id=p_admin_user_id) THEN RAISE EXCEPTION 'Staff user not found'; END IF;
UPDATE public.admin_users SET is_active=false,archived_at=coalesce(archived_at,now()),updated_at=now() WHERE id=p_admin_user_id;
DELETE FROM public.user_presence WHERE admin_user_id=p_admin_user_id; DELETE FROM public.user_daily_online_time WHERE admin_user_id=p_admin_user_id; DELETE FROM public.agent_schedules WHERE admin_user_id=p_admin_user_id; DELETE FROM public.agent_distribution_caps WHERE admin_user_id=p_admin_user_id; DELETE FROM public.agent_daily_targets WHERE agent_id=p_admin_user_id; DELETE FROM public.overflow_recipients WHERE admin_user_id=p_admin_user_id; DELETE FROM public.lead_team_members WHERE admin_user_id=p_admin_user_id;
UPDATE public.sales_leads SET assigned_to=NULL WHERE assigned_to=p_admin_user_id AND status NOT IN ('converted','upgraded','upsell'); UPDATE public.lead_distribution_settings SET overflow_recipient_id=NULL WHERE overflow_recipient_id=p_admin_user_id; UPDATE public.lead_distribution_settings SET solo_agent_id=NULL WHERE solo_agent_id=p_admin_user_id; UPDATE public.round_robin_state SET last_assigned_user_id=NULL WHERE last_assigned_user_id=p_admin_user_id; END $$;
CREATE OR REPLACE FUNCTION public.staff_archive_sources() RETURNS TABLE(table_name text,column_name text,data_type text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.table_name::text,c.column_name::text,c.data_type::text FROM information_schema.columns c JOIN information_schema.tables t ON t.table_schema='public' AND t.table_name=c.table_name AND t.table_type='BASE TABLE' WHERE c.table_schema='public' AND c.data_type IN ('uuid','text') AND c.table_name NOT IN ('staff_leaver_archives','staff_leaver_archive_items','staff_crm_view_observations','staff_crm_departures','staff_crm_departure_items') AND c.column_name IN ('admin_user_id','agent_id','user_id','actor_id','actor_admin_user_id','actor_user_id','performed_by','created_by','changed_by','executed_by','assigned_to','staff_id','admin_id','sale_credit_admin_user_id','agent_admin_user_id','caller_admin_user_id','viewer_admin_user_id','requested_by','approved_by','reviewed_by','decided_by','source_admin_user_id','target_admin_user_id','invited_by','restored_by','updated_by','deleted_by','claimed_by','owner_admin_user_id') ORDER BY 1,2; $$;